	var cam = scene.get_node("World/SourceViewport/SourceCamera")
	var monitor = scene.get_node("HUD/MonitorScreen")

	print("Viewport: ", viewport.name)
	print("Camera path: ", cam.get_path())
	print("Camera is current: ", cam.is_current())
	print("Monitor texture: ", monitor.texture)

	if monitor.texture is ViewportTexture:
		print("Monitor viewport path: ", monitor.texture.viewport_path)
		print("Monitor texture size: ", monitor.texture.get_size())

	print("Test complete")
	quit()

