@onready var source_viewport: SubViewport = $World/SourceViewport
@onready var source_camera: Camera3D = $World/SourceViewport/SourceCamera
@onready var monitor_screen: TextureRect = $HUD/MonitorScreen

func _ready() -> void:
	# Assign the viewport's texture at runtime.
	monitor_screen.texture = source_viewport.get_texture()

## Sets the global transform of the source camera.
func set_camera_pose(pos: Vector3, basis: Basis) -> void:
	# Ensure the camera reference is set (in case called before _ready)
	if not source_camera:
		source_camera = $World/SourceViewport/SourceCamera
	source_camera.global_transform = Transform3D(basis, pos)
